import {contact,displayName,seePeople,introduce} from './identity.js';
import {characterPresent} from './character-stats.js';
import {personalEventPosition} from './personal-event-presence.js';
import {advanceFreeTime} from './free-roam.js';
import {changeRelationship} from './dialogue.js';
export const nursingStudentStories={
 'nursing-student:book':{person:'nursingStudent',episode:1,title:'책갈피가 꽂힌 쪽',location:'library',intro:'반납대에 비슷한 표지의 책 두 권이 놓여 있다. 재킷을 팔에 걸친, 가는 안경테의 학생이 책갈피를 확인하고 조심스럽게 말을 건다.',opening:'저기요. 혹시 그 책, 안쪽에 회색 책갈피 꽂혀 있나요? 제 책이랑 바뀐 것 같아서요.',options:[['names','책을 돌려준 뒤 서로 이름을 묻는다.','저는 백지안이에요. 스물두 살이고, 간호학과 다녀요. 아까 책 확인해주셔서 고마워요.'],['check','책을 펼쳐 읽지 않고 책갈피 색만 확인한 뒤 돌려준다.','아, 맞아요. 감사합니다. 표지가 똑같아서 제가 먼저 확인했어야 했는데.'],['ask','책을 돌려주고 어떤 수업에서 쓰는 책인지 묻는다.','간호학과에서 보는 책이에요. 저 스물두 살이고요. 아, 혹시 이 책 필요하셨던 거면 도서관 책은 이쪽에 있어요.']],second:[['names','헤어지기 전에 서로 이름을 소개한다.','저는 백지안이에요. 스물두 살이고 간호학과 다녀요. 다음에 보면 인사할게요.'],['leave','책이 제대로 돌아갔는지 확인하고 각자 하던 일로 돌아간다.','네, 이제 안 헷갈리겠어요. 잠깐 확인해주셔서 고마워요.'],['mark','본인이 원하면 책 겉에 구분할 표시를 붙여두라고 제안한다.','작은 표시 하나면 되겠네요. 제가 붙여둘게요. 책을 막 펼쳐보지 않고 물어봐주셔서 좋았어요.']]},
 'nursing-student:break':{person:'nursingStudent',episode:2,previous:'nursing-student:book',title:'다 읽지 않아도 되는 날',location:'cafe',intro:'지난번 도서관에서 본 학생이 카페 창가에서 책을 덮는다. 벗어둔 재킷을 의자에 걸고, 비어 있는 옆자리에 놓인 가방을 자기 쪽으로 당긴다.',opening:'지난번에 책 돌려주셨던 분 맞죠? 앉으시려던 거면 여기 비워드릴게요.',options:[['seat','빈자리를 물어보고, 괜찮다고 하면 잠깐 앉는다.','네, 앉으세요. 저도 잠깐 쉬려던 참이에요. 오늘은 같은 줄만 계속 읽고 있어서.'],['rest','본인이 쉬고 싶은 건지 먼저 묻고, 공부 이야기를 계속하지 않는다.','사실 쉬고 싶었어요. 다 읽고 쉬어야 할 것 같았는데… 오늘은 그게 잘 안 되네요.']],second:[['quiet','해결책을 정해주지 않고 잠깐 조용히 쉬다가 일어난다.','이렇게 앉아 있으니까 좀 낫네요. 뭘 해야 쉰 건 줄 알았는데.'],['leave','다음 일정이 있는지 확인하고 붙잡지 않고 헤어진다.','네, 저도 조금만 더 있다가 갈게요. 얘기 들어줘서 고마워요.']]}
};
export function nursingStudentLocation(s){const pin=personalEventPosition(s,'nursingStudent');if(pin)return pin;const m=s.clock.minute;return m>=780&&m<960?'library':m>=960&&m<1020?'cafe':null;}
function nursingStudentTime(s,minutes){return s.clock.minute+minutes<=1080&&!(s.appointments??[]).some(a=>a.status==='pending'&&a.day===s.day&&a.minute>=s.clock.minute&&a.minute<s.clock.minute+minutes);}
export function nursingStudentEventsAt(s,place=s.location){if(s.academics?.registrationPending||s.freeDay?.home||(s.world?.stage??'campus')!=='campus'||!characterPresent(s,'nursingStudent')||nursingStudentLocation(s)!==place)return [];return Object.entries(nursingStudentStories).filter(([id,d])=>{const r=s.personalEvents?.records?.[id],prior=s.personalEvents?.records?.[d.previous];return r?.status!=='completed'&&d.location===place&&nursingStudentTime(s,r?.stage?20:30)&&(!d.previous||prior?.status==='completed'&&s.day>prior.completedDay);}).map(([eventId,d])=>({eventId,person:d.person,title:d.title,resuming:s.personalEvents?.records?.[eventId]?.status==='paused'}));}
export function beginNursingStudentEvent(state,id){if(!nursingStudentEventsAt(state).some(e=>e.eventId===id))throw new Error('지금 같은 장소에서 만날 수 있는지 다시 확인해 주세요.');const s=structuredClone(state);s.personalEvents??={active:null,records:{}};const store=s.personalEvents,old=store.records[id],active=store.records[store.active];if(active?.status==='active')active.status='paused';store.records[id]={...old,eventId:id,person:'nursingStudent',episode:nursingStudentStories[id].episode,status:'active',stage:old?.stage??0,choices:old?.choices??[],day:s.day,location:s.location,until:s.clock.minute+(old?.stage?20:30)};store.active=id;seePeople(s,['nursingStudent']);return s;}
export function nursingStudentEventView(s){const r=s.personalEvents.records[s.personalEvents.active],d=nursingStudentStories[r.eventId];return {...d,...r,options:r.status==='completed'?[]:(r.stage?d.second:d.options).filter(o=>o[0]!=='names'||!contact(s,'nursingStudent').introduced).map(o=>o.slice(0,2))};}
export function progressNursingStudentEvent(state,choice){const r=state.personalEvents.records[state.personalEvents.active],d=nursingStudentStories[r.eventId],option=(r.stage?d.second:d.options).find(o=>o[0]===choice),minutes=r.stage?20:10;if(!option||!nursingStudentEventView(state).options.some(o=>o[0]===choice)||r.status!=='active'||r.day!==state.day||r.location!==state.location||state.clock.minute+minutes>r.until||!nursingStudentTime(state,minutes)||!characterPresent(state,'nursingStudent'))throw new Error('현재 장소·시간과 선택을 확인해 주세요.');const s=advanceFreeTime(state,minutes),rec=s.personalEvents.records[r.eventId];rec.choices.push(choice);rec.last={player:option[1],text:option[2]};seePeople(s,['nursingStudent']);if(choice==='names')introduce(s,'nursingStudent','book-introduction');if(choice==='ask'||choice==='names')s.contacts.nursingStudent.details={...s.contacts.nursingStudent.details,age:22,major:'간호학과'};changeRelationship(s,'nursingStudent','taei',{familiarity:1,trust:choice==='check'||choice==='rest'?1:0});if(r.stage){rec.status='completed';rec.completedDay=s.day;rec.completedMinute=s.clock.minute;rec.result=d.title+' · '+option[1];s.memory.push(`[${s.day}일차] ${displayName(s,'nursingStudent')} · ${rec.result}`);s.lastResult=rec.result;if(!s.known.includes(d.title+' 기록'))s.known.push(d.title+' 기록');}else rec.stage=1;s.pace={count:0,seen:{}};return s;}
